// Seeds the single SiteContent row from frontend/data/seed.json.
//
// Each item in the JSON document is normalized to carry `visible` and
// `order` properties so the CMS can show/hide and reorder without
// schema changes.

import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { PrismaService } from '../../src/common/prisma/prisma.service';

function normalize(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((item, i) => {
      if (item && typeof item === 'object' && !Array.isArray(item)) {
        const obj = item as Record<string, unknown>;
        return {
          visible: obj.visible ?? true,
          order: obj.order ?? i,
          ...(normalize(obj) as Record<string, unknown>),
        };
      }
      return item;
    });
  }
  if (value && typeof value === 'object') {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = normalize(v);
    }
    return out;
  }
  return value;
}

export async function run(prisma: PrismaService) {
  // seeders/ → up two to backend/, up once more to repo root, then frontend/data.
  const seedPath = resolve(
    __dirname,
    '..',
    '..',
    '..',
    'frontend',
    'data',
    'seed.json',
  );
  const raw = readFileSync(seedPath, 'utf-8');
  const parsed = JSON.parse(raw);

  const normalized = normalize(parsed) as Record<string, unknown>;
  normalized.updatedAt = new Date().toISOString();

  await prisma.siteContent.upsert({
    where: { id: 1 },
    update: { data: JSON.stringify(normalized) },
    create: { id: 1, data: JSON.stringify(normalized) },
  });

  console.log('  ✓ SiteContent seeded from data/seed.json');
}

