import { visibleSorted } from '@/lib/cms/db';
import { iconSvg } from '@/lib/pages/icon-svg';
import type { CmsBlogPost, SiteContent } from '@/lib/types';

const HTML_ESCAPES: Record<string, string> = {
  '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
};
function _esc(s: unknown): string {
  if (s == null) return '';
  return String(s).replace(/[&<>"']/g, (c) => HTML_ESCAPES[c] ?? c);
}

export function renderBlogDetail(content: SiteContent | null | undefined, slug?: string): string {
  const docs = content?.documents || {};
  const blogs = visibleSorted<CmsBlogPost>(docs.blogs || []);
  const post: CmsBlogPost = (slug && blogs.find((b) => b.id === slug || b.slug === slug)) || blogs[0] || {};

  const tag = _esc(post.tagLabel || 'Ongoing Research');
  const title = _esc(post.title || 'The Eye of the Heart');
  const standfirst = _esc(post.desc || 'Why being heard by another human heals loneliness, isolation, and depression — the convergent science behind HEARD, and the honest gaps our field study is closing.');
  const author = _esc(post.author || 'Said Mohaddes Sadeqi');
  const initials = _esc(post.initials || 'SM');
  const role = _esc(post.role || 'Founder & President · Third Eye Worldwide');
  const dateStr = _esc(post.date || 'July 2026');
  const readTime = _esc(post.meta || post.readTime || '22 min · Applied research');

  return `
